create table if not exists public.md_source_snapshot(part_num text not null,revision_num text not null,source_hash text not null,last_seen_batch_id uuid,updated_at timestamptz not null default now(),primary key(part_num,revision_num));alter table public.master_import_batch add column if not exists new_rows integer default 0;alter table public.master_import_batch add column if not exists changed_rows integer default 0;alter table public.master_import_batch add column if not exists unchanged_rows integer default 0;create index if not exists ix_source_snapshot_batch on public.md_source_snapshot(last_seen_batch_id);alter table public.md_source_snapshot enable row level security;drop policy if exists "authenticated read md_source_snapshot" on public.md_source_snapshot;create policy "authenticated read md_source_snapshot" on public.md_source_snapshot for select to authenticated using (true);